    let (text, truncated) = last.map_or((String::new(), false), |t| {
        cap_text(&t.final_text, TURN_BYTES_CAP)
    });
    serde_json::json!({
        "resume_id": resume_id,
        "n": last.map_or(0, |t| t.n),
